#!/bin/bash
set -e
cd ~/aps2api 2>/dev/null || { mkdir -p ~/aps2api && cd ~/aps2api; }

echo "======================================"
echo "  aps2api + new-api 一键部署"
echo "======================================"

ARCH=$(uname -m)
case "$ARCH" in
  x86_64)  NEWAPI_BIN="new-api-v1.0.0-rc.25" ;;
  aarch64) NEWAPI_BIN="new-api-arm64-v1.0.0-rc.25" ;;
  *) echo "不支持的架构: $ARCH"; exit 1 ;;
esac

# ========== 安装 Go ==========
echo "[1/4] 准备 Go 环境..."
if ! command -v go &>/dev/null; then
  if command -v apt &>/dev/null; then
    apt update -qq && apt install -y -qq golang-go 2>/dev/null && export PATH=$PATH:/usr/lib/go/bin
  fi
  if ! command -v go &>/dev/null; then
    GO_VER="1.22.5"
    GO_ARCH=$(echo $ARCH | sed 's/x86_64/amd64/;s/aarch64/arm64/')
    wget -q "https://go.dev/dl/go${GO_VER}.linux-${GO_ARCH}.tar.gz" -O /tmp/go.tar.gz
    tar -C /usr/local -xzf /tmp/go.tar.gz
    export PATH=/usr/local/go/bin:$PATH
  fi
fi
echo "Go: $(go version)"

# ========== 编译 aps2api ==========
echo "[2/4] 编译 aps2api..."
echo '' | base64 -d | tar xzf -
CGO_ENABLED=0 go build -trimpath -ldflags="-s -w" -o aps2api ./cmd/vproxy
echo "aps2api 编译完成 ($(ls -lh aps2api | awk '{print $5}'))"

# ========== 下载 new-api ==========
echo "[3/4] 下载 new-api..."
curl -fSL --retry 3 -o new-api   "https://github.com/QuantumNous/new-api/releases/download/v1.0.0-rc.25/${NEWAPI_BIN}"
chmod +x new-api
echo "new-api 下载完成 ($(ls -lh new-api | awk '{print $5}'))"

# ========== 初始化配置 ==========
echo "[4/4] 初始化配置..."
mkdir -p config logs new-api-data/logs

[ ! -f config/config.json ] && echo '{"port_api":2156,"admin_password":"","max_retries":1,"parallel_pool_enabled":true,"parallel_pool_size":15,"race_timeout":60,"stream_idle_timeout_seconds":20,"request_timeout":180}' > config/config.json
[ ! -f config/api_keys.txt ] && echo "# 在此添加 sk- 密钥" > config/api_keys.txt
[ ! -f config/models.json ] && echo '{"version":2,"models":[{"id":"gemini-2.5-flash","enabled":true,"trailing_fix_enabled":false},{"id":"gemini-2.5-pro","enabled":true,"trailing_fix_enabled":false}],"alias_map":{}}' > config/models.json

# ========== 启动 ==========
export TZ=Asia/Shanghai
SESSION_SECRET=$(cat /dev/urandom | tr -dc 'a-f0-9' | head -c 32)
export SESSION_SECRET
export SQLITE_PATH=./new-api-data/one-api.db

echo ""
echo "[启动] aps2api (端口 2156)..."
VPROXY_CONFIG=./config/config.json VPROXY_API_KEYS=./config/api_keys.txt VPROXY_MODELS=./config/models.json nohup ./aps2api > logs/aps2api.log 2>&1 &
echo "  PID: $!"

echo "[启动] new-api (端口 3000)..."
nohup ./new-api --port 3000 --log-dir ./new-api-data/logs > new-api-data/new-api.log 2>&1 &
echo "  PID: $!"

sleep 3

IP=$(hostname -I 2>/dev/null | awk '{print $1}')
echo ""
echo "======================================"
echo "  部署完成！"
echo "======================================"
echo "  new-api:  http://${IP}:3000"
echo "  (首次访问创建管理员账号)"
grep -o '密码: [a-zA-Z0-9]*' logs/aps2api.log 2>/dev/null | head -1
echo "  aps2api:  http://${IP}:2156/admin/"
echo ""
echo "  使用顺序："
echo "  1. 在 aps2api 添加代理节点 → 创建 sk- 密钥"
echo "  2. 在 new-api 添加渠道 → URL: http://127.0.0.1:2156"
echo "======================================"
